#include <bits/stdc++.h>
using namespace std;

long long powMod(long long base, long long exp, long long mod) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long MOD = 998244353;
    vector<vector<long long>> stirling(5005, vector<long long>(5005, 0));
    stirling[1][1] = 1;
    stirling[0][0] = 0;
    for (int i = 1; i <= 5000; i++) {
        stirling[i][i] = 1;
        stirling[i][0] = 0;
    }
    for (int i = 2; i <= 5000; i++) {
        for (int j = 1; j <= i; j++) {
            stirling[i][j] = (stirling[i - 1][j] * j % MOD + stirling[i - 1][j - 1]) % MOD;
        }
    }
    long long n, m;
    int k;
    cin >> n >> m >> k;
    m = powMod(m, MOD - 2, MOD);
    vector<long long> dp(5005, 0);
    dp[0] = 1;
    int limit = (int)std::min(n, (long long)k);
    for (int i = 1; i <= limit; i++) {
        dp[i] = (dp[i - 1] * (n - i + 1)) % MOD;
    }
    long long total = 0;
    for (int i = 1; i <= limit; i++) {
        long long term = dp[i] * powMod(m, i, MOD) % MOD * stirling[k][i] % MOD;
        total = (total + term) % MOD;
    }
    cout << total << "\n";
    return 0;
}

